// MCP tool descriptors. Each pairs a schema with a tool name and description
// so that LLM clients can discover and invoke the underlying RPCs.
var (
	Vcards_CreateVcardTool   = newTool("vcards-create_vcard_v1", `Creates a vCard. POST /v1/vcards body: the vCard itself Server-assigned fields on the request body are ignored: `+"`"+`name`+"`"+`, `+"`"+`uid`+"`"+`, `+"`"+`etag`+"`"+` and the timestamps are set by the server regardless of what is sent. Supply `+"`"+`vcard_id`+"`"+` to choose the final path segment; leave it empty and the server generates one. Not idempotent. Retrying after a timeout may create a second vCard; supply `+"`"+`vcard_id`+"`"+` if the caller needs retry safety. ALREADY_EXISTS     that vcard_id is taken INVALID_ARGUMENT   a field violates its buf.validate constraint PERMISSION_DENIED  caller may not create here`, Vcards_CreateVcardSchemaJSON, Vcards_CreateVcardOutputSchemaJSON, nil, "", nil)
	Vcards_DeleteVcardTool   = newTool("vcards-delete_vcard_v1", `Deletes a vCard. DELETE /v1/{name=vcards/*} Soft delete: the vCard is marked deleted, disappears from List unless `+"`"+`show_deleted`+"`"+` is set, and is purged at `+"`"+`expire_time`+"`"+`. Recover it with Undelete before then. Idempotent in effect but not in reporting: a second delete returns NOT_FOUND rather than succeeding silently. NOT_FOUND          no such vCard ABORTED            etag does not match PERMISSION_DENIED  caller may not delete it`, Vcards_DeleteVcardSchemaJSON, Vcards_DeleteVcardOutputSchemaJSON, nil, "", nil)
	Vcards_GetVcardTool      = newTool("vcards-get_vcard_v1", `Retrieves one vCard. GET /v1/{name=vcards/*} Safe and idempotent. Returns the resource as stored; no field is computed per-caller. Read the `+"`"+`etag`+"`"+` here and pass it back on update or delete to make the write conditional. NOT_FOUND          no such vCard, or it is soft-deleted and `+"`"+`show_deleted`+"`"+` was not set INVALID_ARGUMENT   name does not match vcards/* PERMISSION_DENIED  caller may not read it`, Vcards_GetVcardSchemaJSON, Vcards_GetVcardOutputSchemaJSON, nil, "", nil)
	Vcards_ListVcardsTool    = newTool("vcards-list_vcards_v1", `Lists vCards. GET /v1/vcards Paginated per AIP-158: pass `+"`"+`page_size`+"`"+` (defaults to 50, capped at 1000) and the `+"`"+`next_page_token`+"`"+` from the previous response. An empty `+"`"+`next_page_token`+"`"+` means the last page. Page tokens are opaque and may expire; do not construct or store them. Filtering uses the AIP-160 expression language over the resource's own fields. Results carry no guaranteed order. INVALID_ARGUMENT   malformed filter, or page_size out of range PERMISSION_DENIED  caller may not list this collection`, Vcards_ListVcardsSchemaJSON, Vcards_ListVcardsOutputSchemaJSON, nil, "", nil)
	Vcards_UndeleteVcardTool = newTool("vcards-undelete_vcard_v1", `Restores a soft-deleted vCard. POST /v1/{name=vcards/*}:undelete Valid only before `+"`"+`expire_time`+"`"+`; after that the vCard is gone and this returns NOT_FOUND. Clears `+"`"+`delete_time`+"`"+` and `+"`"+`expire_time`+"`"+` and returns the vCard as it was. NOT_FOUND          no such vCard, or already purged ALREADY_EXISTS     the vCard is not deleted PERMISSION_DENIED  caller may not restore it`, Vcards_UndeleteVcardSchemaJSON, Vcards_UndeleteVcardOutputSchemaJSON, nil, "", nil)
	Vcards_UpdateVcardTool   = newTool("vcards-update_vcard_v1", `Updates a vCard. PATCH /v1/{vcard.name=vcards/*} body: the vCard itself A partial update: only fields named in `+"`"+`update_mask`+"`"+` are written. An empty mask writes every mutable field, which will clear anything the caller left unset -- pass a mask unless that is the intent. OUTPUT_ONLY and IMMUTABLE fields are rejected rather than silently dropped. Idempotent. Pass the `+"`"+`etag`+"`"+` read from Get to make the write conditional. NOT_FOUND          no such vCard ABORTED            etag does not match the stored resource INVALID_ARGUMENT   mask names an unknown or immutable field PERMISSION_DENIED  caller may not modify it`, Vcards_UpdateVcardSchemaJSON, Vcards_UpdateVcardOutputSchemaJSON, nil, "", nil)
)

